const sights = $('Fetch kb_sights').all().map(x => x.json);
const tensions = $('Fetch tensions_wall').all().map(x => x.json);
const journal = $('Fetch journal_entries').all().map(x => x.json);
const guards = $('Fetch drift_guards').all().map(x => x.json);
const appState = $('Fetch app_state').all().map(x => x.json);
const originLog = $('Fetch origin_log').all().map(x => x.json);
const opDoc = $('Fetch operational_doc').all().map(x => x.json);
let rawSchema = $('Fetch schema definitions').first().json.data;
let schemaSql = '';
if (typeof rawSchema === 'string') {
  const trimmed = rawSchema.trim();
  schemaSql = trimmed.startsWith('"') ? JSON.parse(trimmed) : trimmed;
} else if (rawSchema !== undefined && rawSchema !== null) {
  schemaSql = String(rawSchema);
}
const d = new Date().toISOString().split('T')[0];

// ANTI-HOLLOW GATE v2.1 (BB-2293 item 4, Eric ruled 2026-09-09; hardened at BB-2299).
// The ORIGINAL gate tested counts.sights === 0. A capture of 1000 of 1556 rows passed it as healthy
// and 556 kb_sights rows were lost silently for months. A gate keyed to a THRESHOLD expires the day
// a table crosses it; a gate that compares CAPTURED against LIVE has no expiry.
// Live counts come from snapshot_live_counts(), read BEFORE the fetches. THAT COVERS ONE DIRECTION:
// rows ADDED during the run keep captured >= live and still pass. THE OTHER DIRECTION IS A FALSE
// ALARM MODE AND IS NOT COVERED - rows DELETED during the run make captured < live, so a HEALTHY
// backup raises SNAPSHOT TRUNCATED. Fail-closed and accepted on purpose: the gate cannot tell a
// mid-run delete from a truncated capture, and refusing a good backup is cheaper than writing a
// bad one. If you are reading this beside a shortfall of a few rows on a table that was being
// pruned while the snapshot ran, THAT is this mode and not a truncation.
let live = {};
try {
  const lc = $('Fetch live counts').first().json;
  live = (lc && typeof lc === 'object' && !Array.isArray(lc)) ? lc : (Array.isArray(lc) && lc.length ? lc[0] : {});
} catch (e) {
  throw new Error('ANTI-HOLLOW GATE: live counts unavailable (' + e.message + '). Refusing to write a backup that cannot be checked.');
}

// A COUNT IS A NON-NEGATIVE INTEGER OR IT IS NOT A COUNT.
// v2 validated the live side with Number.isFinite(Number(x)). That asks whether a value is COERCIBLE
// to a number, not whether it IS one, and it is true for null, '', false, [], ' ', '0', '1556', [1]
// and [1556]. The zero-coercions made a malformed live side read as a live count of ZERO, after which
// captured < 0 never fires and a truncated capture writes the file. [1556] is worse: it coerces to a
// PLAUSIBLE number, so a malformed live side reads as a MATCHING live side.
// ZERO IS ACCEPTED ON PURPOSE - a genuinely empty table is not a truncated one.
// ASSUMPTION, STATED SO THE HAND WHO MEETS THIS AT 3AM KNOWS IT IS THE GATE WORKING AND NOT AN OUTAGE:
// snapshot_live_counts() is jsonb_build_object over count(*) subselects and emits JSON NUMBERS, so
// this strict check cannot false-alarm on today's producer. The day a producer emits '1556' as a
// STRING, this gate RAISES. AN ARRAY DOES NOT RAISE BY ITSELF: the unwrapping above takes lc[0], so a
// valid counts object inside an array is unwrapped and PASSES; [] and [1556] raise only because what
// comes out of them is not an object of counts. That is correct: an unvalidated live
// side is exactly how the previous defect hid.
const isCount = (v) => typeof v === 'number' && Number.isInteger(v) && v >= 0;

const snapshot = { generated: d, counts: { sights: sights.length, tensions: tensions.length, journal: journal.length, drift_guards: guards.length, app_state: appState.length, origin_log: originLog.length, operational_doc: opDoc.length, schema_chars: schemaSql.length }, live_counts: live, kb_sights: sights, tensions_wall: tensions, journal_entries: journal, drift_guards: guards, app_state: appState, origin_log: originLog, operational_doc: opDoc };

const PAIRS = [['kb_sights','sights'],['tensions_wall','tensions'],['journal_entries','journal'],['drift_guards','drift_guards'],['app_state','app_state'],['origin_log','origin_log'],['operational_doc','operational_doc']];
// badLive DIAGNOSTIC (BB-2327 P3). JSON.stringify CANNOT REPRESENT NaN, Infinity or -Infinity - it
// emits null for all three - so a live side carrying any of them reported the SAME string as a live
// side carrying null, and the reader could not tell an arithmetic failure from a missing key.
// String() is faithful for exactly the non-finite numbers, and every other value keeps its previous
// rendering byte for byte. THIS CHANGES THE MESSAGE ONLY: isCount already rejected all three and
// still does, so what raises and when is unaltered.
const describeLive = (v) => (typeof v === 'number' && !Number.isFinite(v)) ? String(v) : JSON.stringify(v);
const badLive = [];
const shortfalls = [];
for (const pair of PAIRS) {
  const liveN = live[pair[0]];
  const capN = snapshot.counts[pair[1]];
  if (!isCount(liveN)) { badLive.push(pair[0] + '=' + describeLive(liveN)); continue; }
  if (capN < liveN) shortfalls.push(pair[0] + ' captured ' + capN + ' of ' + liveN);
}
if (badLive.length) throw new Error('ANTI-HOLLOW GATE: live count is not a non-negative integer for ' + badLive.join(', ') + '. Refusing to write a backup that cannot be checked.');
if (shortfalls.length) throw new Error('SNAPSHOT TRUNCATED - ' + shortfalls.join('; ') + '. Aborting rather than writing a partial backup. This is the defect that let kb_sights back up 1000 of 1556 rows and pass a zero-test gate.');
if (schemaSql.length < 1000) throw new Error('SCHEMA EXPORT INCOMPLETE - export_schema_definitions() returned ' + schemaSql.length + ' chars. Aborting rather than writing a hollow schema backup.');

const content = JSON.stringify(snapshot, null, 2);
const title = 'TRUTH_SQL_Snapshot_' + d + '.json';
return [
  { json: { content, title, snapshot_date: d, counts: snapshot.counts, live_counts: live } },
  { json: { content: schemaSql, title: 'TRUTH_Schema_Functions_' + d + '.sql', snapshot_date: d, counts: snapshot.counts, live_counts: live } }
];

// Third snapshot file: the four procedure manuals, every version.
// Same anti-hollow rule as Build SQL Snapshot: CAPTURED is compared against LIVE
// (snapshot_live_counts, read before the fetches); a shortfall or a malformed live count refuses the run.
const items = $input.all();
const lc = $('Fetch live counts').first().json;
const live = (lc && typeof lc === 'object' && !Array.isArray(lc)) ? lc : (Array.isArray(lc) && lc.length ? lc[0] : {});
const isCount = (v) => typeof v === 'number' && Number.isInteger(v) && v >= 0;
const TABLES = ['session_load_manual', 'book_walk_manual', 'oracle_manual', 'fold_manual'];
const data = {};
const counts = {};
const liveSub = {};
const problems = [];
for (const t of TABLES) {
  const rows = $('Fetch ' + t).all().map(x => x.json).filter(r => r && typeof r.content === 'string');
  data[t] = rows;
  counts[t] = rows.length;
  liveSub[t] = live[t];
  if (!isCount(live[t])) { problems.push(t + ' live=' + JSON.stringify(live[t])); continue; }
  if (rows.length < live[t]) problems.push(t + ' captured ' + rows.length + ' of ' + live[t]);
}
if (problems.length) throw new Error('PROCEDURE MANUALS SNAPSHOT REFUSED - ' + problems.join('; ') + '. Aborting rather than writing a partial backup.');
const d = items.length ? items[0].json.snapshot_date : new Date().toISOString().split('T')[0];
const snap = Object.assign({ generated: d, counts: counts, live_counts: liveSub }, data);
const extra = { json: { content: JSON.stringify(snap, null, 2), title: 'TRUTH_Procedure_Manuals_' + d + '.json', snapshot_date: d, counts: items.length ? items[0].json.counts : {}, live_counts: items.length ? items[0].json.live_counts : {} } };
return items.concat([extra]);

